# Tutorial: Busca Textual no MongoDB com Índices de Texto

## 1. Estrutura da Coleção

Vamos usar uma coleção `livros` com esta estrutura básica:

```javascript
{
  "_id": ObjectId("..."),
  "titulo": "Dom Casmurro",
  "autor": "Machado de Assis",
  "descricao": "Romance sobre ciúmes e traição na sociedade carioca do século XIX",
  "genero": "Romance",
  "ano": 1899,
  "tags": ["clássico", "literatura brasileira", "realismo"]
}
```

## 2. Criando Índices de Texto

### Índice em um único campo
```javascript
db.livros.createIndex(
  { titulo: "text" }
)
```

### Índice em múltiplos campos (recomendado para buscas abrangentes)
```javascript
db.livros.createIndex(
  { 
    titulo: "text", 
    autor: "text", 
    descricao: "text",
    tags: "text"
  }
)
```

### Índice com pesos (priorizando campos)
```javascript
db.livros.createIndex(
  {
    titulo: "text",
    autor: "text",
    descricao: "text",
    tags: "text"
  },
  {
    weights: {
      titulo: 10,    // 10x mais importante
      autor: 5,      // 5x mais importante
      tags: 3,       // 3x mais importante
      descricao: 1   // peso normal
    },
    name: "indice_busca_livros"
  }
)
```

## 3. Realizando Buscas Textuais

### Busca básica por palavra
```javascript
// Livros que contenham "amor"
db.livros.find(
  { $text: { $search: "amor" } }
)
```

### Busca por múltiplas palavras (OR implícito)
```javascript
// Livros com "amor" OU "ódio"
db.livros.find(
  { $text: { $search: "amor ódio" } }
)
```

### Busca por frase exata
```javascript
db.livros.find(
  { $text: { $search: "\"guerra e paz\"" } }
)
```

### Busca com exclusão de termos
```javascript
// Livros com "amor" mas NÃO "ódio"
db.livros.find(
  { $text: { $search: "amor -ódio" } }
)
```

### Combinação AND/OR
```javascript
// Deve ter "amor" e pode ter "ódio" ou "paixão"
db.livros.find(
  { $text: { $search: "\"amor\" ódio paixão" } }
)
```

## 4. Ordenação por Relevância

```javascript
db.livros.find(
  { $text: { $search: "romance amor" } },
  { score: { $meta: "textScore" } }
).sort(
  { score: { $meta: "textScore" } }
)
```

## 5. Filtros Combinados

```javascript
db.livros.find({
  $text: { $search: "romance" },
  ano: { $gte: 1900 },
  genero: "Romance"
})
```

## 6. Paginação com Relevância

```javascript
db.livros.find(
  { $text: { $search: "clássico literatura" } },
  { score: { $meta: "textScore" } }
)
.sort({ score: { $meta: "textScore" } })
.skip(10)  // Pula 10 resultados
.limit(10) // Limita a 10 resultados
```

## 7. Projeção de Campos

```javascript
db.livros.find(
  { $text: { $search: "machado assis" } },
  {
    titulo: 1,
    autor: 1,
    ano: 1,
    score: { $meta: "textScore" }
  }
)
```

## 8. Exemplo Completo de API (Node.js)

```javascript
const express = require('express');
const router = express.Router();
const Livro = require('../models/Livro');

// GET /api/livros/busca?q=termo&pagina=1&limite=10
router.get('/busca', async (req, res) => {
  try {
    const { q, pagina = 1, limite = 10 } = req.query;

    if (!q || q.trim() === '') {
      return res.status(400).json({ erro: 'Termo de busca é obrigatório' });
    }

    const skip = (pagina - 1) * limite;

    const livros = await Livro.find(
      { $text: { $search: q } },
      { score: { $meta: 'textScore' } }
    )
    .sort({ score: { $meta: 'textScore' } })
    .skip(skip)
    .limit(parseInt(limite));

    const total = await Livro.countDocuments(
      { $text: { $search: q } }
    );

    res.json({
      dados: livros,
      pagina: parseInt(pagina),
      limite: parseInt(limite),
      total,
      totalPaginas: Math.ceil(total / limite)
    });

  } catch (error) {
    res.status(500).json({ erro: 'Erro na busca' });
  }
});
```

## 9. Modelo Mongoose (para Node.js)

```javascript
const mongoose = require('mongoose');

const livroSchema = new mongoose.Schema({
  titulo: String,
  autor: String,
  descricao: String,
  genero: String,
  ano: Number,
  tags: [String]
});

// Criando índice de texto no schema
livroSchema.index({ 
  titulo: 'text', 
  autor: 'text', 
  descricao: 'text',
  tags: 'text' 
}, {
  weights: {
    titulo: 10,
    autor: 5,
    tags: 3,
    descricao: 1
  }
});

module.exports = mongoose.model('Livro', livroSchema);
```

## 10. Dicas Importantes

- **Stop words**: MongoDB ignora palavras como "de", "para", "com" automaticamente
- **Case insensitive**: A busca é insensível a maiúsculas/minúsculas por padrão
- **Stemming**: MongoDB busca por radicais (ex: "correndo" encontra "correr")
- **Idioma**: Configure o idioma para português se necessário:
  ```javascript
  db.livros.createIndex(
    { descricao: "text" },
    { default_language: "portuguese" }
  )
  ```
- **Limitação**: Índices de texto não suportam caracteres especiais como acentos - normalize antes se precisar

Este tutorial cobre o essencial para implementar busca textual eficiente em MongoDB para sua biblioteca de livros.

