## Implementação do Cliente com Retry e Circuit Breaker

```go
// pkg/grpcclient/client.go
package grpcclient

import (
    "context"
    "time"

    "github.com/sony/gobreaker"
    "github.com/avast/retry-go/v4"
    "google.golang.org/grpc"
    "google.golang.org/grpc/status"
    "google.golang.org/grpc/codes"
)

type Client struct {
    conn    *grpc.ClientConn
    cb      *gobreaker.CircuitBreaker
    retryOpts []retry.Option
}

type ClientConfig struct {
    Target           string
    Timeout          time.Duration
    MaxRetries       uint
    RetryDelay       time.Duration
    CircuitBreakerThreshold uint
    CircuitBreakerTimeout   time.Duration
}

func NewClient(ctx context.Context, cfg ClientConfig) (*Client, error) {
    conn, err := grpc.DialContext(ctx, cfg.Target,
        grpc.WithInsecure(),
        grpc.WithBlock(),
        grpc.WithTimeout(cfg.Timeout),
    )
    if err != nil {
        return nil, err
    }

    cb := gobreaker.NewCircuitBreaker(gobreaker.Settings{
        Name:        cfg.Target,
        MaxRequests: cfg.CircuitBreakerThreshold,
        Interval:    time.Minute,
        Timeout:     cfg.CircuitBreakerTimeout,
        ReadyToTrip: func(counts gobreaker.Counts) bool {
            failureRatio := float64(counts.TotalFailures) / float64(counts.Requests)
            return counts.Requests >= 5 && failureRatio >= 0.6
        },
    })

    return &Client{
        conn: conn,
        cb:   cb,
        retryOpts: []retry.Option{
            retry.Attempts(cfg.MaxRetries),
            retry.Delay(cfg.RetryDelay),
            retry.DelayType(retry.BackOffDelay),
            retry.LastErrorOnly(true),
            retry.RetryIf(func(err error) bool {
                // Retenta apenas em erros de rede ou indisponibilidade
                st, ok := status.FromError(err)
                if !ok {
                    return true // erro não-gRPC
                }
                return st.Code() == codes.Unavailable || 
                       st.Code() == codes.DeadlineExceeded ||
                       st.Code() == codes.ResourceExhausted
            }),
        },
    }, nil
}

func (c *Client) Execute(ctx context.Context, fn func(context.Context) error) error {
    // Circuit breaker wrapper
    _, err := c.cb.Execute(func() (interface{}, error) {
        // Retry wrapper
        err := retry.Do(
            func() error {
                return fn(ctx)
            },
            c.retryOpts...,
        )
        return nil, err
    })

    return err
}

func (c *Client) GetConnection() *grpc.ClientConn {
    return c.conn
}
```

## Uso no Cliente Específico

```go
// internal/client/usuario_client.go
package client

import (
    "context"
    "time"

    "meu-servico/pkg/grpcclient"
    pb "meu-servico/pkg/proto/usuario"
)

type UsuarioClient struct {
    client pb.UsuarioServiceClient
    base   *grpcclient.Client
}

func NewUsuarioClient(target string) (*UsuarioClient, error) {
    cfg := grpcclient.ClientConfig{
        Target:           target,
        Timeout:          5 * time.Second,
        MaxRetries:       3,
        RetryDelay:       500 * time.Millisecond,
        CircuitBreakerThreshold: 3,
        CircuitBreakerTimeout:   30 * time.Second,
    }

    base, err := grpcclient.NewClient(context.Background(), cfg)
    if err != nil {
        return nil, err
    }

    return &UsuarioClient{
        client: pb.NewUsuarioServiceClient(base.GetConnection()),
        base:   base,
    }, nil
}

func (c *UsuarioClient) GetUsuario(ctx context.Context, id string) (*pb.Usuario, error) {
    var usuario *pb.Usuario

    err := c.base.Execute(ctx, func(ctx context.Context) error {
        var err error
        usuario, err = c.client.GetUsuario(ctx, &pb.GetUsuarioRequest{Id: id})
        return err
    })

    return usuario, err
}
```

## Servidor gRPC

```go
// internal/server/server.go
package server

import (
    "net"

    "google.golang.org/grpc"
    "google.golang.org/grpc/reflection"
    pb "meu-servico/pkg/proto/usuario"
)

type Server struct {
    grpcServer *grpc.Server
    port       string
}

func NewServer(port string) *Server {
    return &Server{
        port: port,
    }
}

func (s *Server) Start() error {
    lis, err := net.Listen("tcp", ":"+s.port)
    if err != nil {
        return err
    }

    s.grpcServer = grpc.NewServer(
        grpc.UnaryInterceptor(s.unaryInterceptor),
    )

    // Registra serviços
    pb.RegisterUsuarioServiceServer(s.grpcServer, s)

    // Reflection para debugging
    reflection.Register(s.grpcServer)

    return s.grpcServer.Serve(lis)
}

func (s *Server) unaryInterceptor(ctx context.Context, 
    req interface{}, 
    info *grpc.UnaryServerInfo, 
    handler grpc.UnaryHandler) (interface{}, error) {

    // Adicione tracing, métricas, logging aqui
    return handler(ctx, req)
}
