## 5. Resolvers

```javascript
// src/resolvers/Query.js
const db = require('../data/products');

const Query = {
  products: (_, { filter }) => {
    let result = db.getAll();

    if (filter) {
      if (filter.category) {
        result = result.filter(p => p.category === filter.category);
      }
      if (filter.minPrice !== undefined) {
        result = result.filter(p => p.price >= filter.minPrice);
      }
      if (filter.maxPrice !== undefined) {
        result = result.filter(p => p.price <= filter.maxPrice);
      }
      if (filter.inStock !== undefined) {
        result = result.filter(p => p.inStock === filter.inStock);
      }
    }

    return result;
  },

  product: (_, { id }) => {
    return db.getById(id);
  },

  productStats: () => {
    const products = db.getAll();
    const prices = products.map(p => p.price);
    const categories = [...new Set(products.map(p => p.category))];

    return {
      totalProducts: products.length,
      averagePrice: prices.length > 0 
        ? prices.reduce((a, b) => a + b, 0) / prices.length 
        : 0,
      categories
    };
  }
};

module.exports = Query;
```

```javascript
// src/resolvers/Mutation.js
const db = require('../data/products');

const Mutation = {
  createProduct: (_, { input }) => {
    // Validação básica
    if (!input.name || input.price <= 0) {
      throw new Error('Nome é obrigatório e preço deve ser positivo');
    }
    return db.create(input);
  },

  updateProduct: (_, { id, input }) => {
    const updated = db.update(id, input);
    if (!updated) {
      throw new Error(`Produto com ID ${id} não encontrado`);
    }
    return updated;
  },

  deleteProduct: (_, { id }) => {
    return db.delete(id);
  },

  updateStock: (_, { id, inStock }) => {
    const product = db.getById(id);
    if (!product) {
      throw new Error(`Produto com ID ${id} não encontrado`);
    }
    return db.update(id, { inStock });
  }
};

module.exports = Mutation;
```

