Abaixo está uma implementação completa de uma Árvore Binária de Busca (BST) em C++ para armazenar registros de alunos, indexados por matrícula (número inteiro). Inclui as funções de inserção, busca, remoção e um destrutor para liberar memória.

```cpp
#include <iostream>
#include <string>
using namespace std;

// Estrutura que representa um aluno
struct Aluno {
    int matricula;
    string nome;
};

// Nó da árvore binária
struct No {
    Aluno dado;
    No* esquerda;
    No* direita;
    No(int mat, const string& n) : dado{mat, n}, esquerda(nullptr), direita(nullptr) {}
};

class ArvoreAlunos {
private:
    No* raiz;

    // Inserção recursiva
    No* inserirRec(No* no, int matricula, const string& nome) {
        if (no == nullptr) {
            return new No(matricula, nome);
        }
        if (matricula < no->dado.matricula) {
            no->esquerda = inserirRec(no->esquerda, matricula, nome);
        } else if (matricula > no->dado.matricula) {
            no->direita = inserirRec(no->direita, matricula, nome);
        } else {
            // Matrícula já existe: não insere novamente (pode-se tratar como erro)
            cout << "Matrícula " << matricula << " já existe. Ignorando inserção." << endl;
        }
        return no;
    }

    // Busca recursiva (retorna ponteiro para o dado ou nullptr)
    Aluno* buscarRec(No* no, int matricula) {
        if (no == nullptr) return nullptr;
        if (matricula == no->dado.matricula) return &(no->dado);
        if (matricula < no->dado.matricula)
            return buscarRec(no->esquerda, matricula);
        else
            return buscarRec(no->direita, matricula);
    }

    // Encontra o nó com menor valor (mais à esquerda)
    No* encontrarMinimo(No* no) {
        while (no->esquerda != nullptr) no = no->esquerda;
        return no;
    }

    // Remoção recursiva
    No* removerRec(No* no, int matricula) {
        if (no == nullptr) return nullptr;

        if (matricula < no->dado.matricula) {
            no->esquerda = removerRec(no->esquerda, matricula);
        } else if (matricula > no->dado.matricula) {
            no->direita = removerRec(no->direita, matricula);
        } else {
            // Encontrou o nó a ser removido
            // Caso 1: nó folha
            if (no->esquerda == nullptr && no->direita == nullptr) {
                delete no;
                return nullptr;
            }
            // Caso 2: apenas um filho
            else if (no->esquerda == nullptr) {
                No* temp = no->direita;
                delete no;
                return temp;
            } else if (no->direita == nullptr) {
                No* temp = no->esquerda;
                delete no;
                return temp;
            }
            // Caso 3: dois filhos
            else {
                // Encontra o sucessor em ordem (menor da subárvore direita)
                No* sucessor = encontrarMinimo(no->direita);
                // Copia os dados do sucessor para o nó atual
                no->dado.matricula = sucessor->dado.matricula;
                no->dado.nome = sucessor->dado.nome;
                // Remove o sucessor (que agora é uma cópia redundante)
                no->direita = removerRec(no->direita, sucessor->dado.matricula);
            }
        }
        return no;
    }

    // Destrutor auxiliar (percorre em pós-ordem)
    void destruirArvore(No* no) {
        if (no != nullptr) {
            destruirArvore(no->esquerda);
            destruirArvore(no->direita);
            delete no;
        }
    }

    // Impressão em ordem (opcional, para debug)
    void imprimirEmOrdem(No* no) {
        if (no != nullptr) {
            imprimirEmOrdem(no->esquerda);
            cout << "Mat: " << no->dado.matricula << " - Nome: " << no->dado.nome << endl;
            imprimirEmOrdem(no->direita);
        }
    }

public:
    ArvoreAlunos() : raiz(nullptr) {}

    ~ArvoreAlunos() {
        destruirArvore(raiz);
    }

    void inserir(int matricula, const string& nome) {
        raiz = inserirRec(raiz, matricula, nome);
    }

    Aluno* buscar(int matricula) {
        return buscarRec(raiz, matricula);
    }

    void remover(int matricula) {
        raiz = removerRec(raiz, matricula);
    }

    void exibir() {
        if (raiz == nullptr) {
            cout << "Árvore vazia." << endl;
        } else {
            cout << "Alunos em ordem crescente de matrícula:" << endl;
            imprimirEmOrdem(raiz);
        }
    }
};

// Exemplo de uso
int main() {
    ArvoreAlunos arvore;

    // Inserindo alguns alunos
    arvore.inserir(2023001, "Ana Silva");
    arvore.inserir(2023005, "Carlos Souza");
    arvore.inserir(2023003, "Bruna Oliveira");
    arvore.inserir(2023002, "Daniela Costa");
    arvore.inserir(2023004, "Eduardo Lima");

    cout << "Após inserções:" << endl;
    arvore.exibir();

    // Busca
    int matricula = 2023003;
    Aluno* aluno = arvore.buscar(matricula);
    if (aluno != nullptr)
        cout << "Aluno encontrado: " << aluno->nome << " (Matrícula " << aluno->matricula << ")" << endl;
    else
        cout << "Aluno com matrícula " << matricula << " não encontrado." << endl;

    // Remoção (nó folha)
    arvore.remover(2023002);
    cout << "\nApós remover matrícula 2023002:" << endl;
    arvore.exibir();

    // Remoção (nó com dois filhos)
    arvore.remover(2023003);
    cout << "\nApós remover matrícula 2023003:" << endl;
    arvore.exibir();

    // Tentativa de inserir matrícula duplicada
    arvore.inserir(2023001, "Outro Nome"); // será ignorado

    return 0;
}
```

### Funcionalidades implementadas:

1. **Inserção (`inserir`)**  
   Insere um novo aluno mantendo a propriedade da BST (matrículas menores à esquerda, maiores à direita). Matrículas duplicadas são ignoradas com uma mensagem.

2. **Busca (`buscar`)**  
   Retorna um ponteiro para o `Aluno` (se encontrado) ou `nullptr`. A busca é O(log n) no caso médio.

3. **Remoção (`remover`)**  
   Trata todos os três casos:
   - Folha: deleta o nó e retorna `nullptr`.
   - Um filho: substitui o nó pelo filho e deleta o nó original.
   - Dois filhos: substitui

