## 2. Função de Paginação Genérica

```python
def paginate_query(query, page=1, per_page=10, error_out=False):
    """
    Função genérica para paginação eficiente

    Args:
        query: Query SQLAlchemy já filtrada
        page: Número da página (1-based)
        per_page: Itens por página
        error_out: Se True, retorna 404 se página não existir
    """
    # Validação básica
    page = max(1, int(page))
    per_page = min(max(1, int(per_page)), 100)  # Limite máximo de 100

    # Cálculo do offset
    offset = (page - 1) * per_page

    # Consulta eficiente com limit e offset
    items = query.limit(per_page).offset(offset).all()

    # Contagem total (pode ser cacheada em produção)
    total = query.count()

    # Cálculo das métricas de paginação
    total_pages = (total + per_page - 1) // per_page
    has_prev = page > 1
    has_next = page < total_pages

    return {
        'items': items,
        'page': page,
        'per_page': per_page,
        'total': total,
        'total_pages': total_pages,
        'has_prev': has_prev,
        'has_next': has_next,
        'prev_page': page - 1 if has_prev else None,
        'next_page': page + 1 if has_next else None
    }
```

## 3. Rota Flask com Paginação

```python
from flask import Flask, request, jsonify, render_template
from flask_sqlalchemy import SQLAlchemy

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///posts.db'
db.init_app(app)

@app.route('/api/posts', methods=['GET'])
def get_posts():
    try:
        # Parâmetros da requisição com valores padrão
        page = request.args.get('page', 1, type=int)
        per_page = request.args.get('per_page', 10, type=int)

        # Validação
        if page < 1:
            return jsonify({'error': 'Página deve ser maior ou igual a 1'}), 400
        if per_page < 1 or per_page > 100:
            return jsonify({'error': 'per_page deve estar entre 1 e 100'}), 400

        # Query base (pode incluir filtros)
        query = Post.query.order_by(Post.created_at.desc())

        # Paginação eficiente
        result = paginate_query(query, page, per_page)

        # Formata resposta
        response = {
            'data': [item.to_dict() for item in result['items']],
            'pagination': {
                'current_page': result['page'],
                'per_page': result['per_page'],
                'total_items': result['total'],
                'total_pages': result['total_pages'],
                'has_prev': result['has_prev'],
                'has_next': result['has_next']
            },
            'links': {
                'first': f'/api/posts?page=1&per_page={per_page}',
                'prev': f'/api/posts?page={result["prev_page"]}&per_page={per_page}' if result['prev_page'] else None,
                'next': f'/api/posts?page={result["next_page"]}&per_page={per_page}' if result['next_page'] else None,
                'last': f'/api/posts?page={result["total_pages"]}&per_page={per_page}'
            }
        }

        return jsonify(response), 200

    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/posts', methods=['GET'])
def list_posts():
    page = request.args.get('page', 1, type=int)
    per_page = request.args.get('per_page', 10, type=int)

    # Usando paginate() nativo do SQLAlchemy-Flask
    pagination = Post.query.order_by(Post.created_at.desc()).paginate(
        page=page, 
        per_page=per_page, 
        error_out=False
    )

    return render_template('posts.html', pagination=pagination)
```

