Aqui está um programa em C completo que faz exatamente o que você pediu:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_PALAVRAS 10000
#define MAX_TAM 100

// Estrutura para armazenar palavra e sua frequência
typedef struct {
    char palavra[MAX_TAM];
    int frequencia;
} PalavraFreq;

// Função para converter string para minúsculas
void para_minusculo(char *str) {
    for (int i = 0; str[i]; i++) {
        str[i] = tolower(str[i]);
    }
}

// Função de comparação para qsort (ordem decrescente de frequência)
int comparar(const void *a, const void *b) {
    PalavraFreq *pa = (PalavraFreq *)a;
    PalavraFreq *pb = (PalavraFreq *)b;
    return pb->frequencia - pa->frequencia;
}

int main() {
    FILE *arquivo;
    char nome_arquivo[100];
    PalavraFreq palavras[MAX_PALAVRAS];
    int total_palavras = 0;
    char buffer[MAX_TAM];

    printf("Digite o nome do arquivo: ");
    scanf("%99s", nome_arquivo);

    arquivo = fopen(nome_arquivo, "r");
    if (arquivo == NULL) {
        printf("Erro ao abrir o arquivo '%s'\n", nome_arquivo);
        return 1;
    }

    // Inicializa o array de palavras
    for (int i = 0; i < MAX_PALAVRAS; i++) {
        palavras[i].frequencia = 0;
        palavras[i].palavra[0] = '\0';
    }

    // Lê o arquivo palavra por palavra
    while (fscanf(arquivo, "%99s", buffer) == 1) {
        // Remove pontuação do início e fim da palavra
        int inicio = 0;
        int fim = strlen(buffer) - 1;

        while (buffer[inicio] && ispunct(buffer[inicio])) inicio++;
        while (fim >= inicio && ispunct(buffer[fim])) fim--;

        if (inicio > fim) continue; // Palavra vazia (só pontuação)

        // Copia apenas a parte válida
        char palavra_limpa[MAX_TAM];
        strncpy(palavra_limpa, buffer + inicio, fim - inicio + 1);
        palavra_limpa[fim - inicio + 1] = '\0';

        // Converte para minúsculas
        para_minusculo(palavra_limpa);

        // Procura se a palavra já existe no array
        int encontrada = 0;
        for (int i = 0; i < total_palavras; i++) {
            if (strcmp(palavras[i].palavra, palavra_limpa) == 0) {
                palavras[i].frequencia++;
                encontrada = 1;
                break;
            }
        }

        // Se não encontrou, adiciona nova palavra
        if (!encontrada && total_palavras < MAX_PALAVRAS) {
            strcpy(palavras[total_palavras].palavra, palavra_limpa);
            palavras[total_palavras].frequencia = 1;
            total_palavras++;
        }
    }

    fclose(arquivo);

    // Ordena por frequência (decrescente)
    qsort(palavras, total_palavras, sizeof(PalavraFreq), comparar);

    // Exibe as 10 palavras mais comuns
    printf("\n=== TOP 10 PALAVRAS MAIS COMUNS ===\n");
    int limite = (total_palavras < 10) ? total_palavras : 10;

    for (int i = 0; i < limite; i++) {
        printf("%2d. %-20s %d ocorrências\n", 
               i + 1, palavras[i].palavra, palavras[i].frequencia);
    }

    printf("\nTotal de palavras únicas encontradas: %d\n", total_palavras);

    return 0;
}
```

## Como funciona o programa:

1. **Leitura do arquivo**: O programa lê o nome do arquivo e o abre
2. **Processamento**: Lê cada palavra, remove pontuação e converte para minúsculas
3. **Contagem**: Usa um array de estruturas para armazenar cada palavra única e sua frequência
4. **Ordenação**: Usa `qsort` para ordenar por frequência decrescente
5. **Exibição**: Mostra as 10 palavras mais frequentes

## Exemplo de uso:

```
Digite o nome do arquivo: texto.txt

=== TOP 10 PALAVRAS MAIS COMUNS ===
 1. a                   45 ocorrências
 2. de                  38 ocorrências
 3. o                   32 ocorrências
 4. que                 28 ocorrências
 5. e                   25 ocorrências
 6. do                  22 ocorrências
 7. da                  20 ocorrências
 8. em                  18 ocorrências
 9. para                15 ocorrências
10. com                 12 ocorrências

Total de palavras únicas encontradas: 234
```

## Limitações e melhorias possíveis:

- O limite de palavras únicas é 10.000 (ajustável via `#define`)
- Palavras com mais de 99 caracteres são truncadas
- Para arquivos muito grandes, considere usar uma tabela hash em vez de array linear para melhor performance

