```

## Passo 2: Implementação do Scraper

**scraper.go:**

```go
package main

import (
    "fmt"
    "io"
    "net/http"
    "regexp"
    "time"
)

// Result armazena o resultado de cada requisição
type Result struct {
    URL   string
    Title string
    Error error
    Time  time.Duration
}

// extractTitle extrai o título de uma página HTML
func extractTitle(body string) string {
    re := regexp.MustCompile(`<title>(.*?)</title>`)
    matches := re.FindStringSubmatch(body)
    if len(matches) > 1 {
        return matches[1]
    }
    return "Título não encontrado"
}

// fetchTitle faz a requisição HTTP e extrai o título
func fetchTitle(url string) Result {
    start := time.Now()

    client := &http.Client{
        Timeout: 10 * time.Second,
    }

    resp, err := client.Get(url)
    if err != nil {
        return Result{URL: url, Error: fmt.Errorf("erro na requisição: %v", err), Time: time.Since(start)}
    }
    defer resp.Body.Close()

    body, err := io.ReadAll(resp.Body)
    if err != nil {
        return Result{URL: url, Error: fmt.Errorf("erro ao ler resposta: %v", err), Time: time.Since(start)}
    }

    title := extractTitle(string(body))
    return Result{URL: url, Title: title, Time: time.Since(start)}
}
```

## Passo 3: Implementação do Worker Pool

**main.go:**

```go
package main

import (
    "fmt"
    "sync"
    "time"
)

// worker processa URLs do canal de entrada e envia resultados
func worker(id int, urls <-chan string, results chan<- Result, wg *sync.WaitGroup) {
    defer wg.Done()

    for url := range urls {
        fmt.Printf("Worker %d: processando %s\n", id, url)
        result := fetchTitle(url)
        results <- result
    }
}

func main() {
    // Lista de 50 sites para testar
    urls := []string{
        "https://golang.org",
        "https://github.com",
        "https://stackoverflow.com",
        "https://medium.com",
        "https://dev.to",
        // Adicione mais 45 URLs aqui
        "https://google.com",
        "https://youtube.com",
        "https://reddit.com",
        "https://wikipedia.org",
        "https://amazon.com",
    }

    // Preencher até 50 URLs (repetindo alguns para teste)
    for len(urls) < 50 {
        urls = append(urls, fmt.Sprintf("https://example%d.com", len(urls)))
    }

    fmt.Printf("Iniciando scraper com %d URLs...\n\n", len(urls))

    // Configurar o worker pool
    numWorkers := 10
    urlChan := make(chan string, len(urls))
    resultChan := make(chan Result, len(urls))
    var wg sync.WaitGroup

    startTime := time.Now()

    // Iniciar workers
    for i := 0; i < numWorkers; i++ {
        wg.Add(1)
        go worker(i+1, urlChan, resultChan, &wg)
    }

    // Enviar URLs para o canal
    go func() {
        for _, url := range urls {
            urlChan <- url
        }
        close(urlChan)
    }()

    // Coletar resultados em goroutine separada
    go func() {
        wg.Wait()
        close(resultChan)
    }()

    // Processar resultados
    var successCount, errorCount int
    var totalTime time.Duration

    fmt.Println("=== RESULTADOS ===")
    fmt.Println("URL | Título | Tempo")
    fmt.Println("---")

    for result := range resultChan {
        if result.Error != nil {
            fmt.Printf("❌ %s - Erro: %v\n", result.URL, result.Error)
            errorCount++
        } else {
            fmt.Printf("✅ %s | %s | %v\n", result.URL, result.Title, result.Time)
            successCount++
        }
        totalTime += result.Time
    }

    elapsed := time.Since(startTime)

    // Estatísticas
    fmt.Println("\n=== ESTATÍSTICAS ===")
    fmt.Printf("Total de URLs: %d\n", len(urls))
    fmt.Printf("Sucessos: %d\n", successCount)
    fmt.Printf("Erros: %d\n", errorCount)
    fmt.Printf("Workers: %d\n", numWorkers)
    fmt.Printf("Tempo total: %v\n", elapsed)
    fmt.Printf("Tempo médio por URL: %v\n", totalTime/time.Duration(len(urls)))
    fmt.Printf("Velocidade: %.2f URLs/segundo\n", float64(len(urls))/elapsed.Seconds())
}
```

## Passo 4: Como Executar

```bash
go run main.go scraper.go
```

## Explicação do Funcionamento

### Goroutines
- Cada `worker` é uma goroutine que processa URLs de forma independente
- Usamos 10 workers concorrentes (ajustável)
- A função `fetchTitle()` pode rodar em paralelo

### Channels
- `urlChan`: canal bufferizado que distribui URLs entre workers
- `resultChan`: canal bufferizado que coleta resultados dos workers
- Channels garantem comunicação segura entre goroutines

### WaitGroup
- `sync.WaitGroup` sincroniza a finalização de todos workers
- `wg.Add(1)` antes de iniciar cada worker
- `wg.Done()` quando worker termina
- `wg.Wait()` aguarda todos finalizarem

## Variações e Melhorias

### 1. Worker Pool com Número Dinâmico

```go
func main() {
    numWorkers := runtime.NumCPU() * 2 // Adapta ao número de CPUs
    // ... resto do código
}
```

### 2. Com Controle de Rate Limiting

