        result := fetchTitle(url)
        results <- result
    }
}
```

### 3. Com Context para Cancelamento

```go
import "context"

func fetchTitleWithContext(ctx context.Context, url string) Result {
    req, _ := http.NewRequestWithContext(ctx, "GET", url, nil)
    // ... resto do código
}
```

## Boas Práticas

1. **Sempre feche channels** quando não forem mais necessários
2. **Use WaitGroup** para sincronizar goroutines
3. **Bufferize channels** para melhor performance
4. **Implemente timeouts** para evitar deadlocks
5. **Trate erros** adequadamente em cada goroutine
6. **Monitore o uso de memória** com muitas goroutines

