## Implementação do login e geração de token

### 1. Serviço de Token (`src/auth/tokenService.js`)

```javascript
const jwt = require('jsonwebtoken');
require('dotenv').config();

class TokenService {
  generateAccessToken(user) {
    return jwt.sign(
      { 
        id: user.id, 
        email: user.email,
        role: user.role 
      },
      process.env.ACCESS_TOKEN_SECRET,
      { expiresIn: process.env.ACCESS_TOKEN_EXPIRES_IN }
    );
  }

  generateRefreshToken(user) {
    return jwt.sign(
      { id: user.id },
      process.env.REFRESH_TOKEN_SECRET,
      { expiresIn: process.env.REFRESH_TOKEN_EXPIRES_IN }
    );
  }

  verifyAccessToken(token) {
    return jwt.verify(token, process.env.ACCESS_TOKEN_SECRET);
  }

  verifyRefreshToken(token) {
    return jwt.verify(token, process.env.REFRESH_TOKEN_SECRET);
  }
}

module.exports = new TokenService();
```

### 2. Controller de Autenticação (`src/auth/authController.js`)

```javascript
const bcrypt = require('bcrypt');
const tokenService = require('./tokenService');

// Simulação de banco de dados (substitua por seu DB real)
const users = [
  {
    id: 1,
    email: 'usuario@exemplo.com',
    password: '$2b$10$...', // hash gerado com bcrypt
    role: 'user'
  }
];

// Lista para armazenar refresh tokens válidos (em produção, use banco de dados)
let refreshTokens = [];

class AuthController {
  async login(req, res) {
    try {
      const { email, password } = req.body;

      // Validações básicas
      if (!email || !password) {
        return res.status(400).json({ error: 'Email e senha são obrigatórios' });
      }

      // Buscar usuário (substitua por consulta ao banco)
      const user = users.find(u => u.email === email);
      if (!user) {
        return res.status(401).json({ error: 'Credenciais inválidas' });
      }

      // Verificar senha
      const validPassword = await bcrypt.compare(password, user.password);
      if (!validPassword) {
        return res.status(401).json({ error: 'Credenciais inválidas' });
      }

      // Gerar tokens
      const accessToken = tokenService.generateAccessToken(user);
      const refreshToken = tokenService.generateRefreshToken(user);

      // Armazenar refresh token
      refreshTokens.push(refreshToken);

      res.json({
        accessToken,
        refreshToken,
        user: {
          id: user.id,
          email: user.email,
          role: user.role
        }
      });

    } catch (error) {
      console.error('Erro no login:', error);
      res.status(500).json({ error: 'Erro interno do servidor' });
    }
  }

  async refreshToken(req, res) {
    const { refreshToken } = req.body;

    if (!refreshToken) {
      return res.status(401).json({ error: 'Refresh token é obrigatório' });
    }

    // Verificar se o refresh token existe na nossa lista
    if (!refreshTokens.includes(refreshToken)) {
      return res.status(403).json({ error: 'Refresh token inválido' });
    }

    try {
      // Verificar validade do token
      const decoded = tokenService.verifyRefreshToken(refreshToken);

      // Encontrar usuário (substitua por consulta ao banco)
      const user = users.find(u => u.id === decoded.id);
      if (!user) {
        return res.status(403).json({ error: 'Usuário não encontrado' });
      }

      // Gerar novo access token
      const newAccessToken = tokenService.generateAccessToken(user);

      res.json({ accessToken: newAccessToken });

    } catch (error) {
      // Se o refresh token expirou ou é inválido
      refreshTokens = refreshTokens.filter(t => t !== refreshToken);
      return res.status(403).json({ error: 'Refresh token expirado ou inválido' });
    }
  }

  async logout(req, res) {
    const { refreshToken } = req.body;

    // Remover refresh token da lista
    refreshTokens = refreshTokens.filter(t => t !== refreshToken);

    res.json({ message: 'Logout realizado com sucesso' });
  }
}

module.exports = new AuthController();
```

